// Package render turns the intermediate representation into Go source. Its
// output is pure data: one objectDesc literal per file and nothing else, so all
// the behaviour lives in the runtime's hand-written driver and a fix is made once
// rather than in several hundred generated files.
package render

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"

	"solace-semp-workflow/tools/semp-gen/internal/ir"
)

// msgFieldOrder is the order message overrides are emitted in, so a regenerated
// file is byte-identical rather than reordered by map iteration.
var msgFieldOrder = []string{
	"MissingArg", "AlreadyExists", "NotExists", "Converged",
	"WouldCreate", "WouldUpdate", "WouldDelete",
	"Created", "Updated", "Deleted",
	"NoFields", "CheckErr", "CreateErr", "UpdateErr", "DeleteErr",
}

// File is one rendered descriptor file.
type File struct {
	Name    string
	Content []byte
}

// Object renders one object's descriptor file.
func Object(o ir.Object, specVersion string) (*File, error) {
	var b strings.Builder

	fmt.Fprintf(&b, "// Code generated by tools/semp-gen from specs/ (SEMP %s). DO NOT EDIT.\n//\n", specVersion)
	fmt.Fprintf(&b, "// %s: %s\n", o.Definition, describeObject(o))
	if note := o.Platform.Note(); note != "" {
		fmt.Fprintf(&b, "// %s\n", note)
	}
	b.WriteString("\npackage modules\n\nfunc init() {\n\tregisterObject(objectDesc{\n")

	fmt.Fprintf(&b, "\t\tPrefix:       %s,\n", quote(o.Prefix))
	fmt.Fprintf(&b, "\t\tFriendlyName: %s,\n", quote(o.FriendlyName))
	if o.Article != "" && o.Article != "a" {
		fmt.Fprintf(&b, "\t\tArticle:      %s,\n", quote(o.Article))
	}
	fmt.Fprintf(&b, "\t\tScope:        %s,\n", scopeConst(o.Scope))
	if o.IsSingleton {
		b.WriteString("\t\tIsSingleton:  true,\n")
	}

	if len(o.Parents) > 0 {
		b.WriteString("\t\tParents: []parentHop{\n")
		for _, p := range o.Parents {
			fmt.Fprintf(&b, "\t\t\t{Collection: %s, Keys: []keyDesc{", quote(p.Collection))
			for i, k := range p.Keys {
				if i > 0 {
					b.WriteString(", ")
				}
				b.WriteString(renderKey(k))
			}
			b.WriteString("}},\n")
		}
		b.WriteString("\t\t},\n")
	}
	if o.ParentFriendlyName != "" {
		fmt.Fprintf(&b, "\t\tParentFriendlyName: %s,\n", quote(o.ParentFriendlyName))
	}
	if o.Collection != "" {
		fmt.Fprintf(&b, "\t\tCollection:         %s,\n", quote(o.Collection))
	}

	if len(o.OwnKey) > 0 {
		b.WriteString("\t\tOwnKey: []keyDesc{\n")
		for _, k := range o.OwnKey {
			fmt.Fprintf(&b, "\t\t\t%s,\n", renderKey(k))
		}
		b.WriteString("\t\t},\n")
	}
	if o.DisplayKey != 0 {
		fmt.Fprintf(&b, "\t\tDisplayKey: %d,\n", o.DisplayKey)
	}
	if o.HasUpdate {
		b.WriteString("\t\tHasUpdate: true,\n")
	}
	if o.Deprecated != "" {
		fmt.Fprintf(&b, "\t\tDeprecated: %s,\n", quote(o.Deprecated))
	}

	if len(o.Messages) > 0 {
		b.WriteString("\t\tMsg: msgSet{\n")
		for _, field := range msgFieldOrder {
			if v, ok := o.Messages[field]; ok {
				fmt.Fprintf(&b, "\t\t\t%s: %s,\n", field, quote(v))
			}
		}
		b.WriteString("\t\t},\n")
	}

	if len(o.Attributes) > 0 {
		b.WriteString("\t\tFields: []fieldDesc{\n")
		for _, a := range o.Attributes {
			renderAttribute(&b, a, 3)
		}
		b.WriteString("\t\t},\n")
	}

	b.WriteString("\t})\n}\n")

	src, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("gofmt %s: %w", o.Prefix, err)
	}
	return &File{Name: "gen_" + o.Prefix + ".go", Content: src}, nil
}

func renderKey(k ir.Key) string {
	var b strings.Builder
	fmt.Fprintf(&b, "{Name: %s", quote(k.Name))
	if k.Canon != "" {
		fmt.Fprintf(&b, ", Canon: %s", quote(k.Canon))
	}
	if k.Desc != "" {
		fmt.Fprintf(&b, ", Desc: %s", quote(k.Desc))
	}
	if k.Default != "" {
		fmt.Fprintf(&b, ", Default: %s", quote(k.Default))
	}
	b.WriteString("}")
	return b.String()
}

func renderAttribute(b *strings.Builder, a ir.Attribute, depth int) {
	ind := strings.Repeat("\t", depth)

	// A nested group needs its own block; a scalar fits on one line, which keeps
	// a 62-attribute object reviewable in a diff.
	if a.Kind == ir.KindObject {
		fmt.Fprintf(b, "%s{Name: %s,", ind, quote(a.Name))
		if a.Canon != "" {
			fmt.Fprintf(b, " Canon: %s,", quote(a.Canon))
		}
		b.WriteString(" Kind: kindObject,")
		if a.Desc != "" {
			fmt.Fprintf(b, " Desc: %s,", quote(a.Desc))
		}
		b.WriteString(" Fields: []fieldDesc{\n")
		for _, f := range a.Fields {
			renderAttribute(b, f, depth+1)
		}
		fmt.Fprintf(b, "%s}},\n", ind)
		return
	}

	fmt.Fprintf(b, "%s{Name: %s", ind, quote(a.Name))
	if a.Canon != "" {
		fmt.Fprintf(b, ", Canon: %s", quote(a.Canon))
	}
	fmt.Fprintf(b, ", Kind: %s", a.Kind.RuntimeConst())
	if len(a.Enum) > 0 {
		b.WriteString(", Enum: []string{")
		for i, v := range a.Enum {
			if i > 0 {
				b.WriteString(", ")
			}
			b.WriteString(quote(v))
		}
		b.WriteString("}")
	}
	if a.Default != nil {
		fmt.Fprintf(b, ", Default: %s", literal(a.Default))
	}
	for _, f := range []struct {
		name string
		set  bool
	}{
		{"Required", a.Required},
		{"Const", a.Const},
		{"WriteOnly", a.WriteOnly},
		{"Opaque", a.Opaque},
		{"Deprecated", a.Deprecated},
	} {
		if f.set {
			fmt.Fprintf(b, ", %s: true", f.name)
		}
	}
	if len(a.Requires) > 0 {
		fmt.Fprintf(b, ", Requires: %s", stringSlice(a.Requires))
	}
	if len(a.Conflicts) > 0 {
		fmt.Fprintf(b, ", Conflicts: %s", stringSlice(a.Conflicts))
	}
	if a.Desc != "" {
		fmt.Fprintf(b, ", Desc: %s", quote(a.Desc))
	}
	b.WriteString("},\n")
}

func stringSlice(in []string) string {
	sorted := append([]string{}, in...)
	sort.Strings(sorted)
	uniq := sorted[:0]
	var last string
	for i, v := range sorted {
		if i > 0 && v == last {
			continue
		}
		uniq = append(uniq, v)
		last = v
	}
	var b strings.Builder
	b.WriteString("[]string{")
	for i, v := range uniq {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(quote(v))
	}
	b.WriteString("}")
	return b.String()
}

func literal(v any) string {
	switch t := v.(type) {
	case string:
		return quote(t)
	case bool:
		return strconv.FormatBool(t)
	case int:
		return strconv.Itoa(t)
	default:
		return quote(fmt.Sprint(v))
	}
}

// quote renders a Go string literal. %q escapes quotes, backslashes and newlines,
// so a description carrying any of them cannot break the generated source.
func quote(s string) string { return strconv.Quote(s) }

func scopeConst(s ir.Scope) string {
	if s == ir.ScopeVPN {
		return "scopeVPN"
	}
	return "scopeGlobal"
}

func describeObject(o ir.Object) string {
	verbs := []string{"add", "delete"}
	if o.IsSingleton {
		verbs = []string{"update"}
	} else if o.HasUpdate {
		verbs = []string{"add", "update", "delete"}
	}
	return fmt.Sprintf("%d attributes, actions %s.", countAttrs(o.Attributes), strings.Join(verbs, "/"))
}

func countAttrs(attrs []ir.Attribute) int {
	n := 0
	for _, a := range attrs {
		n++
		n += countAttrs(a.Fields)
	}
	return n
}

// Manifest renders the committed list of every registered action, which replaces
// a hand-maintained expected list in the tests: registry, docs and test
// expectations then cannot drift from one another.
func Manifest(spec *ir.Spec) (*File, error) {
	var names []string
	for _, o := range spec.Objects {
		if o.IsSingleton {
			names = append(names, o.Prefix+".update")
			continue
		}
		names = append(names, o.Prefix+".add", o.Prefix+".delete")
		if o.HasUpdate {
			names = append(names, o.Prefix+".update")
		}
	}
	sort.Strings(names)

	var b strings.Builder
	fmt.Fprintf(&b, "// Code generated by tools/semp-gen from specs/ (SEMP %s). DO NOT EDIT.\n\n", spec.Version)
	b.WriteString("package modules\n\n")
	fmt.Fprintf(&b, "// ExpectedModules is every action the generated descriptors register (%d).\n", len(names))
	b.WriteString("// The test suite asserts the registry matches it exactly, so an action that\n")
	b.WriteString("// disappears from a spec bump fails the build instead of vanishing quietly.\n")
	b.WriteString("var ExpectedModules = []string{\n")
	for _, n := range names {
		fmt.Fprintf(&b, "\t%s,\n", quote(n))
	}
	b.WriteString("}\n")

	src, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("gofmt manifest: %w", err)
	}
	return &File{Name: "manifest_generated.go", Content: src}, nil
}

// All renders every file for a spec.
func All(spec *ir.Spec) ([]File, error) {
	out := make([]File, 0, len(spec.Objects)+1)
	for _, o := range spec.Objects {
		f, err := Object(o, spec.Version)
		if err != nil {
			return nil, err
		}
		out = append(out, *f)
	}
	m, err := Manifest(spec)
	if err != nil {
		return nil, err
	}
	out = append(out, *m)

	// Guard against two objects rendering to the same filename, which would make
	// one silently overwrite the other.
	seen := map[string]bool{}
	for _, f := range out {
		if seen[f.Name] {
			return nil, fmt.Errorf("two objects render to %s", f.Name)
		}
		seen[f.Name] = true
	}
	return out, nil
}

// Bytes is a convenience for tests.
func Bytes(f *File) string { return string(bytes.TrimSpace(f.Content)) }
